def main():
    import sys
    import heapq

    def read_integers():
        return list(map(int, sys.stdin.read().split()))

    data = read_integers()
    n = data[0]
    c = data[1]
    a = data[2:]

    def calculate_value(subarray):
        k = len(subarray)
        if k == 0:
            return 0
        exclude_count = k // c
        if exclude_count == 0:
            return sum(subarray)
        subarray.sort()
        return sum(subarray[exclude_count:])

    min_sum = float('inf')
    current_subarray = []
    current_sum = 0

    for i in range(n):
        current_subarray.append(a[i])
        current_sum += a[i]

