import sys
import heapq

def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, c = readints()
    a = readints()

    def value_of_subarray(subarray):
        if not subarray:
            return 0
        k = len(subarray)
        exclude_count = k // c
        heap = subarray[:]
        heapq.heapify(heap)
        for _ in range(exclude_count):
            heapq.heappop(heap)
        return sum(heap)

    min_sum = float('inf')
    current_sum = 0
    current_subarray = []

    for i in range(n):
        current_subarray.append(a[i])
        current_sum += a[i]
        if i == n - 1 or len(current_subarray) >= c:
            current_value = value_of_subarray(current_subarray)
            min_sum = min(min_sum, current_sum - current_value)
            current_subarray = []
            current_sum = 0

    print(min_sum)

if __name__ == "__main__":
    main()
